class_name CTEngine
extends RefCounted
## FFT-faithful clocktick engine (Battle 1 slice). All integer math, no RNG.
## Every tick, each unit gains CT equal to Speed; at CT >= 100 the unit acts,
## then CT -= 100. Simulated here as a deterministic forecast of upcoming turns.

static func forecast(units: Array, count: int) -> Array:
	var ct := {}
	for u in units:
		ct[str(u["id"])] = 0
	var out: Array = []
	var guard := 0
	while out.size() < count and guard < 1000:
		guard += 1
		for u in units:
			ct[str(u["id"])] = int(ct[str(u["id"])]) + int(u["speed"])
		var ready: Array = []
		for u in units:
			if int(ct[str(u["id"])]) >= 100:
				ready.append(u)
		ready.sort_custom(func(a, b):
			var ca := int(ct[str(a["id"])])
			var cb := int(ct[str(b["id"])])
			if ca != cb:
				return ca > cb
			return int(a["speed"]) > int(b["speed"]))
		for u in ready:
			out.append(str(u["name"]))
			ct[str(u["id"])] = int(ct[str(u["id"])]) - 100
			if out.size() >= count:
				break
	return out
